const { exec } = require('child_process');
const util = require('util');
const execPromise = util.promisify(exec);

const batPath = 'C:\\laragon\\www\\ramco-scraper2\\run_sundry.bat';
const startedAt = new Date().toISOString();

// Open a visible cmd window that runs the batch (like double-clicking it).
// cmd /k keeps the window open after the batch finishes so you can review output.
// n8n does not wait for the window to close — it returns immediately after launch.
const command = `start "Sundry Scraper" cmd /k "${batPath}"`;

try {
  await execPromise(command, {
    cwd: 'C:\\laragon\\www\\ramco-scraper2',
    windowsHide: false
  });
  return [{
    json: {
      success: true,
      message: 'Sundry batch launched in a visible cmd window',
      batPath,
      startedAt,
      launchedAt: new Date().toISOString(),
      note: 'The cmd window shows live output. It stays open (cmd /k) until you close it.'
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      message: 'Failed to launch batch window',
      error: error.message,
      startedAt,
      finishedAt: new Date().toISOString()
    }
  }];
}
